[CmdletBinding()] param([int]$WithinDays=14,[string]$Path="$PSScriptRoot\..\Reports\password-expiration.csv")
Import-Module ActiveDirectory;$now=Get-Date;$end=$now.AddDays($WithinDays);Get-ADUser -Filter {Enabled -eq $true -and PasswordNeverExpires -eq $false} -Properties msDS-UserPasswordExpiryTimeComputed,Department|ForEach-Object{$exp=[datetime]::FromFileTime($_.'msDS-UserPasswordExpiryTimeComputed');if($exp -ge $now -and $exp -le $end){[pscustomobject]@{Name=$_.Name;SamAccountName=$_.SamAccountName;Department=$_.Department;Expires=$exp;DaysRemaining=[math]::Ceiling(($exp-$now).TotalDays)}}}|Export-Csv $Path -NoTypeInformation;"Saved $Path"
